package revisitledger.resolve;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;
import java.nio.file.*;import java.util.*;import revisitledger.index.*;import revisitledger.model.*;
import static revisitledger.resolve.ResolutionFixtures.*;
class SelectorResolverTest {
 @TempDir Path tmp;
 RecordFacts p=provider("p.warc","<p>","http://example/X%2F/",DATE,DIGEST);
 CandidateResolution resolve(RecordIndex i)throws Exception{return new SelectorResolver().resolve(i,key("r.warc"),ChoiceSet.empty(i.corpusFingerprint()));}
 @Test void idOnly()throws Exception{try(var i=index(tmp,p,revisit("r.warc",Map.of("WARC-Refers-To","<p>")))){var r=resolve(i);assertEquals("resolved",r.status());assertEquals(Optional.of(p.key()),r.optionalChosen());}}
 @Test void exactUriDateOnly()throws Exception{try(var i=index(tmp,p,revisit("r.warc",Map.of("WARC-Refers-To-Target-URI","http://example/X%2F/","WARC-Refers-To-Date",DATE)))){assertEquals("resolved",resolve(i).status());}}
 @Test void fractionalInstantsAgreeWithoutFloats()throws Exception{var q=provider("p.warc","<p>","http://x/","2020-01-01T00:00:00.100Z",DIGEST);try(var i=index(tmp,q,revisit("r.warc",Map.of("WARC-Refers-To-Target-URI","http://x/","WARC-Refers-To-Date","2020-01-01T00:00:00.1Z")))){assertEquals("resolved",resolve(i).status());}}
 @Test void agreeingSelectors()throws Exception{try(var i=index(tmp,p,revisit("r.warc",Map.of("WARC-Refers-To","<p>","WARC-Refers-To-Target-URI",p.header("WARC-Target-URI").orElseThrow(),"WARC-Refers-To-Date",DATE)))){assertEquals("resolved",resolve(i).status());}}
 @Test void conflictingSelectorsDoNotFallback()throws Exception{try(var i=index(tmp,p,revisit("r.warc",Map.of("WARC-Refers-To","<p>","WARC-Refers-To-Target-URI","http://else/","WARC-Refers-To-Date",DATE)))){var r=resolve(i);assertEquals("selector_conflict",r.status());assertTrue(r.optionalChosen().isEmpty());}}
 @Test void missingExplicitIdNeverUsesDigestFallback()throws Exception{try(var i=index(tmp,p,revisit("r.warc",Map.of("WARC-Refers-To","<absent>")))){assertEquals("missing_in_corpus",resolve(i).status());}}
 @Test void partialSelectorReported()throws Exception{try(var i=index(tmp,p,revisit("r.warc",Map.of("WARC-Refers-To","<p>","WARC-Refers-To-Target-URI",p.header("WARC-Target-URI").orElseThrow())))){var r=resolve(i);assertEquals("resolved",r.status());assertTrue(r.findings().stream().anyMatch(f->f.code().equals("partial_selector")));}}
 @Test void partialSelectorWithoutUniqueIdBlocks()throws Exception{try(var i=index(tmp,p,revisit("r.warc",Map.of("WARC-Refers-To-Target-URI",p.header("WARC-Target-URI").orElseThrow())))){assertEquals("unsupported",resolve(i).status());}}
 @Test void duplicateIdAmbiguous()throws Exception{var q=provider("q.warc","<p>","http://q/",DATE,DIGEST);try(var i=index(tmp,p,q,revisit("r.warc",Map.of("WARC-Refers-To","<p>")))){var r=resolve(i);assertEquals("ambiguous",r.status());assertEquals(2,collect(r.sortedCandidates()).size());}}
 @Test void partialCannotDisambiguateDuplicateId()throws Exception{var q=provider("q.warc","<p>","http://q/",DATE,DIGEST);try(var i=index(tmp,p,q,revisit("r.warc",Map.of("WARC-Refers-To","<p>","WARC-Refers-To-Target-URI",p.header("WARC-Target-URI").orElseThrow())))){assertEquals("ambiguous",resolve(i).status());}}
 @Test void sameDigestAlternativeNotCorruption()throws Exception{var q=provider("q.warc","<q>","http://q/",DATE,DIGEST);try(var i=index(tmp,q,p,revisit("r.warc",Map.of()))){var r=resolve(i);assertEquals("ambiguous",r.status());assertEquals(List.of(p.key(),q.key()),collect(r.sortedCandidates()).stream().map(RecordFacts::key).toList());assertTrue(r.findings().stream().noneMatch(f->f.code().equals("digest_mismatch")));}}
 @Test void sameTargetDateAmbiguous()throws Exception{var q=provider("q.warc","<q>",p.header("WARC-Target-URI").orElseThrow(),DATE,DIGEST);try(var i=index(tmp,p,q,revisit("r.warc",Map.of("WARC-Refers-To-Target-URI",q.header("WARC-Target-URI").orElseThrow(),"WARC-Refers-To-Date",DATE)))){assertEquals("ambiguous",resolve(i).status());}}
 @Test void uniqueDigestOnlyResolves()throws Exception{try(var i=index(tmp,p,revisit("r.warc",Map.of()))){assertEquals("resolved",resolve(i).status());}}
 @Test void choiceSelectsOnlyEnumeratedAlternative()throws Exception{var q=provider("q.warc","<q>","http://q/",DATE,DIGEST);try(var i=index(tmp,p,q,revisit("r.warc",Map.of()))){var c=new ChoiceSet(i.corpusFingerprint(),Map.of(key("r.warc"),q.key()));var r=new SelectorResolver().resolve(i,key("r.warc"),c);assertEquals("resolved",r.status());assertEquals(Optional.of(q.key()),r.optionalChosen());}}
 @Test void staleChoiceCannotBind()throws Exception{try(var i=index(tmp,p,revisit("r.warc",Map.of()))){assertEquals("input_incomplete",new SelectorResolver().resolve(i,key("r.warc"),new ChoiceSet("stale",Map.of(key("r.warc"),p.key()))).status());}}
 @Test void choiceCannotBypassConflict()throws Exception{try(var i=index(tmp,p,revisit("r.warc",Map.of("WARC-Refers-To","<p>","WARC-Refers-To-Target-URI","http://else/","WARC-Refers-To-Date",DATE)))){assertEquals("selector_conflict",new SelectorResolver().resolve(i,key("r.warc"),new ChoiceSet(i.corpusFingerprint(),Map.of(key("r.warc"),p.key()))).status());}}
 @Test void choiceOutsideCandidatesBlocks()throws Exception{try(var i=index(tmp,p,revisit("r.warc",Map.of()))){assertEquals("selector_conflict",new SelectorResolver().resolve(i,key("r.warc"),new ChoiceSet(i.corpusFingerprint(),Map.of(key("r.warc"),key("absent.warc")))).status());}}
 @Test void exactUriNoNormalization()throws Exception{for(String uri:List.of("http://example/X%2f/","http://example/X%2F","http://EXAMPLE/X%2F/")){try(var i=index(tmp,p,revisit("r.warc",Map.of("WARC-Refers-To-Target-URI",uri,"WARC-Refers-To-Date",DATE)))){assertEquals("missing_in_corpus",resolve(i).status());}}}
 @Test void unsupportedProfileAndDigestBlock()throws Exception{for(var extra:List.of(Map.of("WARC-Profile","http://unknown/"),Map.of("WARC-Payload-Digest","md5:abc"))){try(var i=index(tmp,p,revisit("r.warc",extra))){assertEquals("unsupported",resolve(i).status());}}}
 @Test void unsupportedSelectorPrecisionBlocks()throws Exception{try(var i=index(tmp,p,revisit("r.warc",Map.of("WARC-Refers-To","<p>","WARC-Refers-To-Date","2020")))){assertEquals("unsupported",resolve(i).status());}}

 @Test void concreteDigestMismatchCannotBeChosenAway()throws Exception{var wrong=provider("p.warc","<p>","http://p/",DATE,OTHER);try(var i=index(tmp,wrong,revisit("r.warc",Map.of("WARC-Refers-To","<p>")))){assertEquals("digest_mismatch",new SelectorResolver().resolve(i,key("r.warc"),new ChoiceSet(i.corpusFingerprint(),Map.of(key("r.warc"),wrong.key()))).status());}}
 @Test void incompleteCorpusNeverResolves()throws Exception{try(var i=RecordIndex.create(tmp,64L<<20)){i.record(p);i.record(revisit("r.warc",Map.of("WARC-Refers-To","<p>")));i.file(new FileFacts("p.warc","f".repeat(64),1,false));i.file(new FileFacts("r.warc","f".repeat(64),1,true));i.seal(new ScanSummary(2,2,false));assertEquals("input_incomplete",resolve(i).status());}}
 @Test void missingPayloadDigestWithExplicitIdStillUsesVerifiedProvider()throws Exception{var r=record("r.warc",1,"revisit","<r>","http://r/",DATE,null,Map.of("WARC-Refers-To","<p>"));try(var i=index(tmp,p,r)){assertEquals("resolved",resolve(i).status());}}
 @Test void digestOnlyWithoutDigestIsUnsupported()throws Exception{var r=record("r.warc",1,"revisit","<r>","http://r/",DATE,null,Map.of());try(var i=index(tmp,p,r)){assertEquals("unsupported",resolve(i).status());}}
 @Test void emptyExplicitIdDoesNotBecomeDigestOnly()throws Exception{try(var i=index(tmp,p,revisit("r.warc",Map.of("WARC-Refers-To","")))){assertEquals("missing_in_corpus",resolve(i).status());}}
 @Test void idAbsentButUriDateFoundIsConflict()throws Exception{try(var i=index(tmp,p,revisit("r.warc",Map.of("WARC-Refers-To","<absent>","WARC-Refers-To-Target-URI",p.header("WARC-Target-URI").orElseThrow(),"WARC-Refers-To-Date",DATE)))){assertEquals("selector_conflict",resolve(i).status());}}
 @Test void partialDateMustAgree()throws Exception{try(var i=index(tmp,p,revisit("r.warc",Map.of("WARC-Refers-To","<p>","WARC-Refers-To-Date","2020-01-02T00:00:00Z")))){assertEquals("selector_conflict",resolve(i).status());}}

 @Test void candidateIteratorCannotOutliveIndex()throws Exception{CandidateResolution r;try(var i=index(tmp,p,revisit("r.warc",Map.of()))){r=resolve(i);}assertThrows(java.io.IOException.class,r::sortedCandidates);}
 @Test void choicesAreImmutableAfterConstruction()throws Exception{try(var i=index(tmp,p,revisit("r.warc",Map.of()))){var mutable=new HashMap<RecordKey,RecordKey>();var c=new ChoiceSet(i.corpusFingerprint(),mutable);mutable.put(key("r.warc"),key("other.warc"));assertEquals("resolved",new SelectorResolver().resolve(i,key("r.warc"),c).status());assertThrows(UnsupportedOperationException.class,()->c.bindings().put(key("r.warc"),p.key()));}}

 @Test void absentConsumerBindingDoesNotPassCorpusValidation()throws Exception{try(var i=index(tmp,p,revisit("r.warc",Map.of()))){var c=new ChoiceSet(i.corpusFingerprint(),Map.of(key("absent.warc"),p.key()));assertFalse(c.validFor(i));}}
 @Test void absentProviderBindingDoesNotPassCorpusValidation()throws Exception{try(var i=index(tmp,p,revisit("r.warc",Map.of()))){var c=new ChoiceSet(i.corpusFingerprint(),Map.of(key("r.warc"),key("absent.warc")));assertFalse(c.validFor(i));}}
}
